// Parse only the markup generated by the popup's own templates. This fallback is used when
// a page forbids Trusted Types policy creation; dictionary values must still be escaped by
// the caller. Unknown markup fails closed before the fragment is attached to the page.
function zooBuildSafeFragment(doc, html) {
  var tags = ['div', 'h1', 'h2', 'ul', 'li', 'span', 'button', 'form', 'p', 'label', 'input', 'datalist'];
  var attributes = ['id', 'class', 'type', 'title', 'aria-label', 'hidden', 'disabled', 'required', 'list', 'autocomplete', 'data-zd-action', 'data-zd-vi', 'data-zd-modal-cancel'];
  var entities = {'amp': '&', 'lt': '<', 'gt': '>', 'quot': '"', '#39': "'"};
  function decode(text) {
    return text.replace(/&([^;]*);|&/g, function(match, name) {
      if (!Object.prototype.hasOwnProperty.call(entities, name)) throw new Error('Unsupported HTML entity');
      return entities[name];
    });
  }
  var root = doc.createDocumentFragment();
  var stack = [{name: '', node: root}];
  var position = 0;
  while (position < html.length) {
    var next = html.indexOf('<', position);
    if (next < 0) next = html.length;
    if (next > position) stack[stack.length - 1].node.appendChild(doc.createTextNode(decode(html.slice(position, next))));
    if (next === html.length) break;
    var end = html.indexOf('>', next + 1);
    if (end < 0) throw new Error('Malformed HTML tag');
    var body = html.slice(next + 1, end);
    var closing = /^\/([a-z][a-z0-9]*)$/.exec(body);
    if (closing) {
      if (stack.length === 1 || stack[stack.length - 1].name !== closing[1]) throw new Error('Malformed HTML nesting');
      stack.pop();
    } else {
      var opening = /^([a-z][a-z0-9]*)([\s\S]*)$/.exec(body);
      if (!opening || tags.indexOf(opening[1]) < 0) throw new Error('Unsupported HTML tag');
      var element = doc.createElement(opening[1]);
      var rest = opening[2];
      while (rest) {
        var attribute = /^\s+([a-z][a-z0-9-]*)(?:="([^"]*)")?/.exec(rest);
        if (!attribute) throw new Error('Malformed HTML attribute');
        if (attributes.indexOf(attribute[1]) < 0) throw new Error('Unsupported HTML attribute');
        element.setAttribute(attribute[1], decode(attribute[2] || ''));
        rest = rest.slice(attribute[0].length);
      }
      stack[stack.length - 1].node.appendChild(element);
      if (opening[1] !== 'input') stack.push({name: opening[1], node: element});
    }
    position = end + 1;
  }
  if (stack.length !== 1) throw new Error('Malformed HTML nesting');
  return root;
}
